-- ============================================================================
-- V1 - Criacao das tabelas (versao ORACLE)
--   Prefixo T_CLYVOJ_ para nao conflitar com as tabelas T_CLYVO_ de outro trabalho
--   bigint             -> NUMBER(19)
--   auto_increment     -> GENERATED BY DEFAULT AS IDENTITY
--   varchar / decimal  -> VARCHAR2 / NUMBER
--   enum (...)         -> VARCHAR2 + CHECK (o Oracle nao tem tipo enum)
--   engine=InnoDB      -> removido (existe so no MySQL)
-- ============================================================================

    create table T_CLYVOJ_ANIMAL (
        dt_nascimento_animal date not null,
        peso_animal number(5,2) not null,
        id_animal number(19) generated by default as identity,
        id_responsavel number(19) not null,
        nr_microchip_animal varchar2(20),
        rg_animal varchar2(20),
        especie_animal varchar2(50) not null,
        raca_animal varchar2(50) not null,
        nm_animal varchar2(100) not null,
        primary key (id_animal)
    );

    create table T_CLYVOJ_CLINICA (
        id_clinica number(19) generated by default as identity,
        cnpj_clinica varchar2(20) not null,
        email varchar2(100) not null,
        nm_clinica varchar2(100) not null,
        senha varchar2(255) not null,
        st_contrato varchar2(20) not null check (st_contrato in ('ATIVO','INATIVO')),
        primary key (id_clinica)
    );

    create table T_CLYVOJ_CLINICA_VET (
        id_clinica number(19) not null,
        id_clinica_vet number(19) generated by default as identity,
        id_veterinario number(19) not null,
        primary key (id_clinica_vet)
    );

    create table T_CLYVOJ_CONSULTA (
        dt_consulta date not null,
        id_animal number(19) not null,
        id_consulta number(19) generated by default as identity,
        id_vet_cli number(19) not null,
        historico_consulta varchar2(200) not null,
        st_consulta varchar2(20) not null check (st_consulta in ('CANCELADA','EM_ANDAMENTO','FUTURA','PASSADA')),
        primary key (id_consulta)
    );

    create table T_CLYVOJ_ENDERECO_ANIMAL (
        id number(19) generated by default as identity,
        id_animal number(19) not null,
        cep varchar2(9) not null,
        nr_rua varchar2(15) not null,
        bairro varchar2(20) not null,
        cidade varchar2(20) not null,
        complemento varchar2(20),
        estado varchar2(20) not null,
        pais varchar2(20) not null,
        logradouro varchar2(50) not null,
        primary key (id)
    );

    create table T_CLYVOJ_ENDERECO_CLINICA (
        id number(19) generated by default as identity,
        id_clinica number(19) not null,
        cep varchar2(9) not null,
        nr_rua varchar2(15) not null,
        bairro varchar2(20) not null,
        cidade varchar2(20) not null,
        complemento varchar2(20),
        estado varchar2(20) not null,
        pais varchar2(20) not null,
        logradouro varchar2(50) not null,
        primary key (id)
    );

    create table T_CLYVOJ_ENDERECO_RESPONSAVEL (
        id number(19) generated by default as identity,
        id_responsavel number(19) not null,
        cep varchar2(9) not null,
        nr_rua varchar2(15) not null,
        bairro varchar2(20) not null,
        cidade varchar2(20) not null,
        complemento varchar2(20),
        estado varchar2(20) not null,
        pais varchar2(20) not null,
        logradouro varchar2(50) not null,
        primary key (id)
    );

    create table T_CLYVOJ_MEDICAMENTO (
        qt_dias number(10) not null check (qt_dias >= 1),
        qt_frequencia number(10) not null check (qt_frequencia >= 1),
        qt_medicamento number(10) not null check (qt_medicamento >= 1),
        vl_dose number(5,2) not null,
        id number(19) generated by default as identity,
        id_prescricao number(19) not null,
        un_dose varchar2(20) not null,
        un_frequencia varchar2(20) not null,
        nm_medicamento varchar2(100) not null,
        forma_farmaceutica varchar2(20) not null check (forma_farmaceutica in ('LIQUIDA','SEMI_SOLIDA','SOLIDA')),
        primary key (id)
    );

    create table T_CLYVOJ_PRESCRICAO (
        dt_emissao date not null,
        dt_expiracao date not null,
        id_consulta number(19) not null,
        id_prescricao number(19) generated by default as identity,
        observacoes_gerais varchar2(255),
        primary key (id_prescricao)
    );

    create table T_CLYVOJ_RESPONSAVEL (
        id_responsavel number(19) generated by default as identity,
        cpf_responsavel varchar2(14) not null,
        nr_telefone_responsavel varchar2(20) not null,
        ds_email varchar2(100) not null,
        nm_responsavel varchar2(100) not null,
        primary key (id_responsavel)
    );

    create table T_CLYVOJ_VACINACAO (
        dt_vacinacao_efetuada date,
        dt_vacinacao_prevista date not null,
        id_animal number(19) not null,
        id_vacinacao number(19) generated by default as identity,
        nm_vacina varchar2(40) not null,
        st_vacinacao varchar2(20) not null check (st_vacinacao in ('ATRASADA','CANCELADA','EFETUADA','PENDENTE')),
        primary key (id_vacinacao)
    );

    create table T_CLYVOJ_VET (
        id_vet number(19) generated by default as identity,
        cpf_vet varchar2(14) not null,
        crmv_vet varchar2(20) not null,
        email varchar2(100) not null,
        nm_vet varchar2(100) not null,
        senha varchar2(255) not null,
        primary key (id_vet)
    );

    create table T_CLYVOJ_USUARIO (
        id number(19) generated by default as identity,
        id_clinica number(19),
        id_veterinario number(19),
        senha varchar2(255),
        username varchar2(255),
        tipo varchar2(20) check (tipo in ('CLINICA','VETERINARIO')),
        primary key (id)
    );
